import functools
import inspect
from typing import ForwardRef, Any, Callable, Dict
from fastapi.dependencies.utils import get_typed_signature, get_typed_annotation

class A:
    def method(self, x: "A") -> None:
        pass

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

# Wrap the method
A.wrapped_method = wrapper(A.method)

def test_wrapped_method_type_inference():
    try:
        sig = get_typed_signature(A.wrapped_method)
        # The first param is 'self', the second is 'x'
        params = list(sig.parameters.values())
        # params[0] is self
        # params[1] is x
        x_param = params[1]
        print(f"Annotation for x: {x_param.annotation}")
        # It should be resolved to A
        assert x_param.annotation is A
        print("Success!")
    except Exception as e:
        print(f"Failed: {e}")
        raise e

if __name__ == "__main__":
    test_wrapped_method_type_inference()
